css:
.reit-sim-container {
    padding: 24px;
    background: #0a0f1e;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #e6e8ec;
}
.reit-sim-header {
    background: linear-gradient(135deg, #0f1830 0%, #1a2744 100%);
    border-left: 4px solid #d4af37;
    border-radius: 6px;
    padding: 24px 28px;
    margin-bottom: 24px;
    box-shadow: 0 6px 20px rgba(0,0,0,0.4);
}
.reit-sim-header-inner {
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 16px;
}
.reit-sim-header h1 {
    color: #d4af37;
    font-size: 1.6rem;
    letter-spacing: 0.04em;
    margin: 0 0 4px 0;
    font-weight: 700;
}
.reit-sim-subtitle {
    color: #97a3b4;
    font-size: 0.82rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
}
.reit-sim-period-badge {
    background: rgba(212,175,55,0.1);
    border: 1px solid rgba(212,175,55,0.4);
    color: #d4af37;
    padding: 8px 18px;
    border-radius: 4px;
    font-size: 0.85rem;
    letter-spacing: 0.08em;
    font-weight: 600;
}
.reit-sim-period-badge span { margin: 0 3px; }

.reit-sim-progress-track {
    margin-top: 18px;
    height: 4px;
    background: rgba(255,255,255,0.08);
    border-radius: 2px;
    overflow: hidden;
}
.reit-sim-progress-fill {
    height: 100%;
    background: linear-gradient(90deg, #d4af37, #5b8dd6);
    border-radius: 2px;
    transition: width 0.4s ease;
}

.reit-sim-banner {
    background: rgba(212,175,55,0.12);
    border: 1px solid rgba(212,175,55,0.45);
    border-left: 4px solid #d4af37;
    color: #f0dfa8;
    border-radius: 6px;
    padding: 14px 20px;
    margin-bottom: 24px;
    font-size: 0.92rem;
    line-height: 1.5;
}

.reit-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 14px;
    margin-bottom: 24px;
}
.reit-sim-kpi-card {
    background: #111b30;
    border: 1px solid #1f2d48;
    border-radius: 6px;
    padding: 18px 20px;
    position: relative;
    overflow: hidden;
    transition: border-color 0.2s ease, transform 0.2s ease;
}
.reit-sim-kpi-card:hover {
    border-color: #2d4166;
    transform: translateY(-2px);
}
.reit-sim-kpi-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0;
    width: 3px;
    height: 100%;
    background: linear-gradient(180deg, #d4af37, #5b8dd6);
}
.reit-sim-kpi-label {
    color: #93a0b5;
    font-size: 0.68rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    margin-bottom: 6px;
    font-weight: 600;
}
.reit-sim-kpi-value {
    font-size: 1.7rem;
    font-weight: 700;
    color: #e6e8ec;
    letter-spacing: -0.01em;
}
.reit-sim-kpi-value-gold { color: #d4af37; }
.reit-sim-kpi-value-warn { color: #e88f66; }

.reit-sim-briefing {
    background: linear-gradient(180deg, #121d38 0%, #0e1629 100%);
    border: 1px solid #1f2d48;
    border-radius: 8px;
    padding: 24px 28px;
    margin-bottom: 24px;
}
.reit-sim-briefing-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 10px;
    margin-bottom: 10px;
}
.reit-sim-briefing-label {
    color: #d4af37;
    font-size: 0.68rem;
    text-transform: uppercase;
    letter-spacing: 0.15em;
    font-weight: 600;
}
.reit-sim-status-pill {
    background: rgba(91,141,214,0.14);
    border: 1px solid rgba(91,141,214,0.4);
    color: #9dbdf0;
    border-radius: 999px;
    padding: 3px 12px;
    font-size: 0.7rem;
    letter-spacing: 0.06em;
    font-weight: 600;
    text-transform: uppercase;
}
.reit-sim-briefing h2 {
    color: #e6e8ec;
    font-size: 1.2rem;
    font-weight: 700;
    margin: 0 0 14px 0;
}
#briefingText {
    color: #bcc5d3;
    line-height: 1.65;
    font-size: 0.95rem;
}

.reit-sim-outcome {
    background: #10203a;
    border: 1px solid #24406b;
    border-left: 4px solid #5b8dd6;
    border-radius: 8px;
    padding: 18px 24px;
    margin-bottom: 24px;
}
.reit-sim-outcome-label {
    color: #9dbdf0;
    font-size: 0.68rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    font-weight: 700;
    margin-bottom: 8px;
}
#roundNarrative {
    color: #d3dbe8;
    line-height: 1.6;
    font-size: 0.95rem;
}

.reit-sim-controls {
    background: #0f1830;
    border: 1px solid #1f2d48;
    border-radius: 8px;
    padding: 24px 28px;
    margin-bottom: 24px;
}
.reit-sim-controls h3 {
    color: #d4af37;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    margin: 0 0 18px 0;
    font-weight: 600;
}
.reit-sim-round-panel {
    border: none;
    margin: 0;
    padding: 0;
    min-width: 0;
}
.reit-sim-round-panel legend {
    color: #93a0b5;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    font-weight: 600;
    padding: 0;
    margin: 0 0 4px 0;
    width: auto;
    float: none;
    border: none;
}
.reit-sim-round-panel label {
    display: block;
    color: #bcc5d3;
    font-size: 0.85rem;
    margin-top: 14px;
    margin-bottom: 6px;
    font-weight: 500;
}
.reit-sim-round-panel input[type="number"],
.reit-sim-round-panel select {
    background: #0a1124;
    border: 1px solid #2d3f62;
    color: #e6e8ec;
    border-radius: 4px;
    padding: 9px 12px;
    width: 100%;
    font-size: 0.95rem;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.reit-sim-round-panel input[type="number"]:focus,
.reit-sim-round-panel select:focus,
.reit-sim-round-panel input[type="number"]:focus-visible,
.reit-sim-round-panel select:focus-visible {
    outline: none;
    border-color: #d4af37;
    box-shadow: 0 0 0 3px rgba(212,175,55,0.25);
}
.reit-sim-round-panel input[type="number"]:disabled,
.reit-sim-round-panel select:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}
.reit-sim-round-panel select option {
    background: #111b30;
    color: #e6e8ec;
}
.reit-sim-help {
    color: #8b97a8;
    font-size: 0.78rem;
    line-height: 1.5;
    margin: 6px 0 0 0;
}
.reit-sim-button-row {
    display: flex;
    gap: 12px;
    margin-top: 24px;
    flex-wrap: wrap;
}
.reit-sim-controls .btn-primary {
    background: linear-gradient(135deg, #d4af37 0%, #b8941f 100%);
    border: none;
    color: #0a0f1e;
    padding: 11px 28px;
    font-weight: 700;
    letter-spacing: 0.04em;
    border-radius: 4px;
    box-shadow: 0 4px 14px rgba(212,175,55,0.3);
    transition: transform 0.15s ease, box-shadow 0.15s ease;
}
.reit-sim-controls .btn-primary:hover:not(:disabled) {
    transform: translateY(-1px);
    box-shadow: 0 6px 18px rgba(212,175,55,0.45);
}
.reit-sim-controls .btn-outline-secondary {
    background: transparent;
    border: 1px solid #2d3f62;
    color: #bcc5d3;
    border-radius: 4px;
}
.reit-sim-controls .btn-outline-secondary:hover {
    background: #1a2340;
    color: #e6e8ec;
}
.reit-sim-controls .btn:focus-visible {
    outline: 3px solid #9dbdf0;
    outline-offset: 2px;
}

.reit-sim-charts {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    margin-bottom: 24px;
}
.reit-sim-chart-panel {
    background: #111b30;
    border: 1px solid #1f2d48;
    border-radius: 8px;
    padding: 20px;
    height: 320px;
}

.reit-sim-history {
    background: #111b30;
    border: 1px solid #1f2d48;
    border-radius: 8px;
    padding: 20px;
    overflow-x: auto;
}
.reit-sim-history table {
    color: #e6e8ec;
    margin-bottom: 0;
    width: 100%;
}
.reit-sim-history table thead th {
    color: #d4af37;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    border-bottom: 1px solid #2d3f62;
    font-weight: 600;
    padding: 10px 12px;
    white-space: nowrap;
}
.reit-sim-history table tbody td {
    color: #bcc5d3;
    font-size: 0.9rem;
    border-top: 1px solid #1a2340;
    padding: 10px 12px;
}
.reit-sim-history table.table-striped tbody tr:nth-of-type(odd) {
    background: rgba(255,255,255,0.02);
}

/* ---- LPAC debrief, rendered inside the framework completion modal ---------
   The modal itself is framework-themed (light by default), so this card
   carries its own background and colours and must not inherit them. */
.reit-sim-complete {
    background: #0f1830;
    color: #e6e8ec;
    border-radius: 8px;
    border-top: 4px solid #d4af37;
    padding: 24px 26px;
    text-align: left;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}
.reit-sim-complete h3 {
    color: #d4af37;
    font-size: 1.15rem;
    font-weight: 700;
    margin: 0 0 4px 0;
}
.reit-sim-complete .reit-sim-complete-sub {
    color: #97a3b4;
    font-size: 0.8rem;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    margin-bottom: 18px;
}
.reit-sim-complete .reit-sim-rating {
    display: inline-block;
    background: rgba(212,175,55,0.14);
    border: 1px solid rgba(212,175,55,0.45);
    color: #f0dfa8;
    border-radius: 999px;
    padding: 5px 16px;
    font-weight: 700;
    font-size: 0.92rem;
    margin-bottom: 16px;
}
.reit-sim-complete-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
    gap: 10px;
    margin-bottom: 18px;
}
.reit-sim-complete-metric {
    background: #14203a;
    border: 1px solid #24334f;
    border-radius: 6px;
    padding: 12px 14px;
}
.reit-sim-complete-metric .m-label {
    color: #93a0b5;
    font-size: 0.64rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    font-weight: 700;
    margin-bottom: 4px;
}
.reit-sim-complete-metric .m-value {
    color: #e6e8ec;
    font-size: 1.25rem;
    font-weight: 700;
}
.reit-sim-complete-metric .m-value.neg { color: #e88f66; }
.reit-sim-complete-metric .m-value.pos { color: #7fc99a; }
.reit-sim-complete-context {
    background: #0c1526;
    border-left: 3px solid #5b8dd6;
    border-radius: 4px;
    padding: 12px 16px;
    color: #bcc5d3;
    font-size: 0.86rem;
    line-height: 1.6;
    margin-bottom: 18px;
}
.reit-sim-complete h4 {
    color: #9dbdf0;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    font-weight: 700;
    margin: 0 0 8px 0;
}
.reit-sim-complete ul {
    margin: 0;
    padding-left: 20px;
}
.reit-sim-complete li {
    color: #d3dbe8;
    font-size: 0.9rem;
    line-height: 1.6;
    margin-bottom: 6px;
}

@media (max-width: 768px) {
    .reit-sim-container { padding: 16px; }
    .reit-sim-header-inner { flex-direction: column; align-items: flex-start; }
    .reit-sim-charts { grid-template-columns: 1fr; }
    .reit-sim-kpi-grid { grid-template-columns: repeat(2, 1fr); }
    .reit-sim-kpi-value { font-size: 1.4rem; }
    .reit-sim-briefing, .reit-sim-controls, .reit-sim-outcome { padding: 18px 16px; }
    .reit-sim-button-row .btn { width: 100%; }
    .reit-sim-complete { padding: 18px 16px; }
    .reit-sim-complete-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 420px) {
    .reit-sim-kpi-grid { grid-template-columns: 1fr; }
}

