(function() {
    'use strict';

    /* ------------------------------------------------------------------ *
     * Scenario constants — Quillmoor Capital Partners, Fund III workout.
     * ------------------------------------------------------------------ */
    var ASSETS_TOTAL        = 11;    // Class-B suburban office assets at t0
    var UPREIT_ASSETS       = 4;     // Raleigh pair + Phoenix pair (Round 4)
    var UPREIT_PARTIAL      = 2;     // Raleigh pair only
    var RESERVE_ENVELOPE    = 18;    // $M of Fund III reserves
    var CONTRIBUTED_EQUITY  = 152;   // $M of LP + GP capital contributed to date
    var OPENING_EQUITY      = 113;   // $M of remaining NAV at t0
    var MATURITY_WALL       = 78;    // $M of CMBS maturing inside 18 months
    var FUND_LIFE_YEARS     = 8;     // "year seven of eight" per the Round 5 briefing
    var TAX_RATE            = 0.25;  // blended federal + state LTCG and §1250 recapture
    var GAIN_FRACTION       = 0.35;  // embedded gain as a share of relinquished value
    var ASSET_VALUE         = 28;    // $M gross per relinquished asset
    var RESERVE_LEVERAGE    = 0.35;  // $ of maturity relief per $1 of reserve deployed
    var QI_UNINSURED_HAIRCUT = 0.85; // 1 - 0.15 expected total-loss probability
    var QI_FAILURE_ODDS     = 15;    // % — the tail the haircut prices, quoted in the debrief

    var SELECT_IDS = ['triageStrategyInput', 'qiSelectionInput', 'identificationRuleInput',
                      'cmbsStrategyInput', 'bankruptcyThreatInput', 'upreitDecisionInput',
                      'fundExtensionInput', 'promoteWaiverInput'];
    var NUMBER_IDS = ['reserveAllocationInput', 'relinquishedCountInput', 'lockupDaysInput'];

    class REITPlayAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'The REIT Play';
            this.version = '2.0.0';
            this._wired = false;
        }

        /* =============================================================== *
         * i18n helper. window.mySimulation.t() delegates to vcI18n, which
         * does interpolate {vars} — but we substitute locally as well so a
         * missing-key fallback (which returns the raw key) never leaks
         * un-substituted placeholders into the UI.
         * =============================================================== */
        _t(key, vars) {
            var sim = window.mySimulation;
            var out = key;
            try {
                if (sim && typeof sim.t === 'function') out = sim.t(key, vars);
            } catch (e) { out = key; }
            if (typeof out !== 'string') out = String(key);
            if (vars) {
                Object.keys(vars).forEach(function(k) {
                    out = out.split('{' + k + '}').join(String(vars[k]));
                });
            }
            return out;
        }

        _notify(key, vars, kind) {
            try {
                window.mySimulation.uiManager.showNotification(this._t(key, vars), kind || 'warning');
            } catch (e) { /* notifications are advisory only */ }
        }

        /* =============================================================== *
         * State shape
         * =============================================================== */
        _seedDomain() {
            return {
                portfolioValue: 373,
                totalDebt: 260,
                fundEquity: OPENING_EQUITY,
                contributedEquity: CONTRIBUTED_EQUITY,
                cashReserves: RESERVE_ENVELOPE,
                reservesDeployed: 0,
                taxDeferred: 0,
                recourseExposure: 0,
                lpTrust: 70,
                maturityWallCovered: 0,
                maturityWallTotal: MATURITY_WALL,
                assetsTotal: ASSETS_TOTAL,
                assetsRemaining: ASSETS_TOTAL,
                assetsHandledKeys: 0,
                assetsExchanged: 0,
                assetsRolledUp: 0,
                assetsSold: 0,
                fundLifeYears: FUND_LIFE_YEARS,
                scoreHistory: [],
                irrHistory: [],
                equityHistory: [],
                taxDeferredHistory: [],
                trustHistory: []
            };
        }

        /* Selects start unanswered so an untouched Submit cannot auto-play a round. */
        _seedDecisions() {
            return {
                triageStrategy: '',
                reserveAllocation: 50,
                relinquishedCount: 3,
                qiSelection: '',
                identificationRule: '',
                cmbsStrategy: '',
                bankruptcyThreat: '',
                upreitDecision: '',
                lockupDays: 365,
                fundExtension: '',
                promoteWaiver: ''
            };
        }

        _seriesKeys() {
            return ['scoreHistory', 'irrHistory', 'equityHistory', 'taxDeferredHistory', 'trustHistory'];
        }

        /* True when domainState carries the marks of at least one played round. */
        _hasPlayedRounds(ds) {
            if (!ds) return false;
            var played = this._seriesKeys().some(function(k) {
                return Array.isArray(ds[k]) && ds[k].length > 0;
            });
            return played
                || ds.assetsHandledKeys > 0 || ds.assetsExchanged > 0 || ds.assetsRolledUp > 0
                || ds.taxDeferred > 0 || ds.maturityWallCovered > 0 || ds.recourseExposure > 0
                || ds.reservesDeployed > 0
                || (typeof ds.fundEquity === 'number' && ds.fundEquity !== OPENING_EQUITY)
                || (typeof ds.lpTrust === 'number' && ds.lpTrust !== 70);
        }

        initialize(state) {
            var seed = this._seedDomain();
            var ds = state.domainState;
            var noHistory = !Array.isArray(state.history) || state.history.length === 0;

            if (!ds || Object.keys(ds).length === 0) {
                state.domainState = seed;
            } else if (noHistory && this._hasPlayedRounds(ds)) {
                /* undoLastPeriod() emptied the history and then called us. A populated
                   domainState here would replay on top of itself and double-count. */
                state.domainState = seed;
                state.results = {};
            } else {
                /* Backfill only what a save predates — never clobber loaded values. */
                Object.keys(seed).forEach(function(k) {
                    if (ds[k] === undefined || ds[k] === null) ds[k] = seed[k];
                });
                this._seriesKeys().forEach(function(k) {
                    if (!Array.isArray(ds[k])) ds[k] = [];
                });
                if (typeof ds.assetsRemaining !== 'number' || !isFinite(ds.assetsRemaining)) {
                    ds.assetsRemaining = Math.max(0, ASSETS_TOTAL
                        - (ds.assetsHandledKeys || 0) - (ds.assetsExchanged || 0)
                        - (ds.assetsRolledUp || 0) - (ds.assetsSold || 0));
                }
            }

            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = this._seedDecisions();
            }

            this._wire();
            this._paint(state);
            this._showNarrative(state);
        }

        /* =============================================================== *
         * Event wiring. The engine repaints nothing round-specific, so the
         * panel, briefing, narrative and completion lock are all driven from
         * the framework's own events — never from a deferred timer that would
         * read state.currentPeriod after the engine had already advanced it.
         * =============================================================== */
        _wire() {
            if (this._wired) return;
            var sim = window.mySimulation;
            if (!sim || !sim.eventBus || typeof sim.eventBus.on !== 'function') return;
            this._wired = true;
            var self = this;

            sim.eventBus.on('period:submitted', function(result) {
                self._paint(sim.state);
                self._showNarrative(sim.state);
                if (result && result.complete) self._lockDown(sim.state);
            });
            sim.eventBus.on('period:undone', function(st) {
                var s = st || sim.state;
                self._unlock();
                self._paint(s);
                self._showNarrative(s);
            });
            sim.eventBus.on('framework:initialized', function() {
                self._paint(sim.state);
                self._showNarrative(sim.state);
                self._afterLoad(sim.state);
            });
            sim.eventBus.on('state:loaded', function() {
                self._paint(sim.state);
                self._showNarrative(sim.state);
            });
            document.addEventListener('express:langchanged', function() {
                self._paint(sim.state);
                self._showNarrative(sim.state);
                self._localiseCharts();
                if (self._isComplete(sim.state)) self._lockDown(sim.state);
                try { sim.renderHistoryTable(); } catch (e) { /* engine already guards */ }
            });
        }

        /* =============================================================== *
         * Completion lifecycle. PeriodManager.submitPeriod() returns
         * {complete:true} WITHOUT incrementing, so a finished run persists with
         * currentPeriod === maxPeriods and the engine's own
         * `currentPeriod > maxPeriods` guards never fire. The adapter has to
         * own the lock-out itself.
         * =============================================================== */
        _isComplete(state) {
            var st = state || {};
            var max = parseInt(st.maxPeriods, 10) || 5;
            var rounds = Array.isArray(st.history) ? st.history.length : 0;
            return rounds >= max || (parseInt(st.currentPeriod, 10) || 1) > max;
        }

        _lockDown(state) {
            var st = state || (window.mySimulation && window.mySimulation.state) || {};
            var max = parseInt(st.maxPeriods, 10) || 5;
            var banner = document.getElementById('runCompleteBanner');
            if (banner) {
                banner.textContent = this._t('run_complete_banner', { total: max });
                banner.style.display = 'block';
            }
            var btn = document.getElementById('nextPeriodBtn');
            if (btn) { btn.disabled = true; btn.setAttribute('aria-disabled', 'true'); }
        }

        _unlock() {
            var banner = document.getElementById('runCompleteBanner');
            if (banner) { banner.style.display = 'none'; banner.textContent = ''; }
            var btn = document.getElementById('nextPeriodBtn');
            if (btn) {
                btn.disabled = false;
                btn.removeAttribute('aria-disabled');
                btn.removeAttribute('data-usf-disabled');
                btn.style.opacity = '';
                btn.style.cursor = '';
            }
            SELECT_IDS.concat(NUMBER_IDS).forEach(function(id) {
                var el = document.getElementById(id);
                if (el) el.disabled = false;
            });
        }

        /* Reload of a finished run: the engine leaves the inputs live, so lock
           them here and put the LPAC report back on screen. */
        _afterLoad(state) {
            if (!this._isComplete(state)) { this._unlock(); return; }
            var self = this;
            setTimeout(function() {
                try { window.mySimulation.uiManager.disableInputs(); } catch (e) { /* optional */ }
                self._lockDown(state);
                try {
                    if (window.mySimulation && typeof window.mySimulation.showCompletion === 'function') {
                        window.mySimulation.showCompletion();
                    }
                } catch (e) { /* modal is optional */ }
            }, 0);
        }

        /* =============================================================== *
         * Decision harvesting + validation
         * =============================================================== */
        _readSelect(d, key, id, allowed, labelKey) {
            var el = document.getElementById(id);
            var v = el ? String(el.value === null || el.value === undefined ? '' : el.value).trim()
                       : String(d[key] === undefined || d[key] === null ? '' : d[key]).trim();
            if (allowed.indexOf(v) === -1) {
                this._notify('warn_choose', { field: this._t(labelKey) });
                return false;
            }
            d[key] = v;
            return true;
        }

        _readNumber(id, min, max, warnKey, warnVars, integerOnly) {
            var el = document.getElementById(id);
            var raw = el ? String(el.value === null || el.value === undefined ? '' : el.value).trim() : '';
            if (raw === '') { this._notify(warnKey, warnVars); return null; }
            var n = parseFloat(raw);
            if (!isFinite(n) || n < min || n > max) { this._notify(warnKey, warnVars); return null; }
            if (integerOnly) {
                if (Math.abs(n - Math.round(n)) > 1e-9) { this._notify(warnKey, warnVars); return null; }
                n = Math.round(n);
            }
            return n;
        }

        _maxRelinquish(ds) {
            var remaining = (ds && typeof ds.assetsRemaining === 'number' && isFinite(ds.assetsRemaining))
                ? ds.assetsRemaining : ASSETS_TOTAL;
            return Math.max(1, Math.min(6, remaining - UPREIT_ASSETS));
        }

        validateDecisions(decisions) {
            var sim = window.mySimulation;
            var state = (sim && sim.state) ? sim.state : { currentPeriod: 1, domainState: {}, history: [] };
            var period = parseInt(state.currentPeriod, 10) || 1;
            var ds = state.domainState || {};
            var d = decisions || {};

            if (this._isComplete(state)) {
                this._notify('warn_completed', { total: parseInt(state.maxPeriods, 10) || 5 }, 'info');
                return false;
            }

            if (period === 1) {
                if (!this._readSelect(d, 'triageStrategy', 'triageStrategyInput',
                        ['aggressive', 'balanced', 'defensive'], 'triage_label')) return false;
                var reserve = this._readNumber('reserveAllocationInput', 0, 100, 'reserve_warning');
                if (reserve === null) return false;
                d.reserveAllocation = reserve;
            } else if (period === 2) {
                var cap = this._maxRelinquish(ds);
                var count = this._readNumber('relinquishedCountInput', 1, cap, 'relinq_warning',
                    { max: cap, needed: UPREIT_ASSETS }, true);
                if (count === null) return false;
                d.relinquishedCount = count;
                if (!this._readSelect(d, 'qiSelection', 'qiSelectionInput',
                        ['cheap', 'mid', 'premium'], 'qi_label')) return false;
                if (!this._readSelect(d, 'identificationRule', 'identificationRuleInput',
                        ['three', 'two_hundred', 'ninety_five'], 'id_rule_label')) return false;
            } else if (period === 3) {
                if (!this._readSelect(d, 'cmbsStrategy', 'cmbsStrategyInput',
                        ['refi', 'modify', 'dpo', 'keys'], 'cmbs_label')) return false;
                if (!this._readSelect(d, 'bankruptcyThreat', 'bankruptcyThreatInput',
                        ['no', 'yes'], 'bankruptcy_label')) return false;
            } else if (period === 4) {
                if (!this._readSelect(d, 'upreitDecision', 'upreitDecisionInput',
                        ['accept', 'counter', 'reject', 'partial'], 'upreit_label')) return false;
                var lock = this._readNumber('lockupDaysInput', 90, 720, 'lockup_warning', null, true);
                if (lock === null) return false;
                d.lockupDays = lock;
            } else if (period === 5) {
                if (!this._readSelect(d, 'fundExtension', 'fundExtensionInput',
                        ['terminate', 'extend1', 'extend2'], 'extension_label')) return false;
                if (!this._readSelect(d, 'promoteWaiver', 'promoteWaiverInput',
                        ['none', 'partial', 'full'], 'promote_label')) return false;
            }
            return true;
        }

        /* =============================================================== *
         * Scoring
         * =============================================================== */
        calculateResults(state) {
            var d = state.decisions || {};
            var ds = state.domainState || {};
            var period = parseInt(state.currentPeriod, 10) || 1;

            var roundScore = 0;
            var equityDelta = 0;
            var taxDeferredDelta = 0;
            var trustDelta = 0;
            var debtAddressed = 0;
            var recourseAdded = 0;
            var narrativeKey = '';

            if (period === 1) {
                var keysBack = 0;
                if (d.triageStrategy === 'aggressive') {
                    keysBack = 3; debtAddressed += 30; equityDelta -= 15; trustDelta -= 5;
                    roundScore = 65; narrativeKey = 'r1_aggressive_narr';
                } else if (d.triageStrategy === 'defensive') {
                    keysBack = 0; debtAddressed += 8; equityDelta -= 5; trustDelta -= 8;
                    roundScore = 52; narrativeKey = 'r1_defensive_narr';
                } else {
                    keysBack = 2; debtAddressed += 22; equityDelta -= 8; trustDelta += 3;
                    roundScore = 78; narrativeKey = 'r1_balanced_narr';
                }
                ds.assetsHandledKeys += keysBack;
                ds.assetsRemaining = Math.max(0, (ds.assetsRemaining === undefined ? ASSETS_TOTAL : ds.assetsRemaining) - keysBack);

                /* v1.0.0: cashReserves = 18 * (alloc/100) — i.e. deploying 100% of the
                   envelope LEFT you the full $18M. The input is the share DEPLOYED, so
                   what remains is the complement. */
                var alloc = Math.max(0, Math.min(100, parseFloat(d.reserveAllocation)));
                if (!isFinite(alloc)) alloc = 0;
                var deployed = Math.round(RESERVE_ENVELOPE * (alloc / 100) * 10) / 10;
                ds.reservesDeployed = deployed;
                ds.cashReserves = Math.round((RESERVE_ENVELOPE - deployed) * 10) / 10;

                /* Deployed equity cures maturing debt (curtailment, TI/LC, lease-up).
                   v1.0.0 read reserveAllocation and then used it for nothing at all. */
                debtAddressed += Math.round(deployed * RESERVE_LEVERAGE * 10) / 10;

                /* The capital plan has to match the strategy: little point sinking TI
                   into assets you are handing back, and no point fighting for every
                   asset with the cheque book closed. */
                var target = d.triageStrategy === 'aggressive' ? 30
                           : (d.triageStrategy === 'defensive' ? 85 : 55);
                var fit = 6 - Math.abs(alloc - target) * 0.18;
                if (fit < -8) fit = -8;
                roundScore += Math.round(fit * 10) / 10;
                if (alloc > 90) trustDelta -= 2;   // no dry powder left for the exchange
            } else if (period === 2) {
                var cap = this._maxRelinquish(ds);
                var count = parseInt(d.relinquishedCount, 10);
                if (!isFinite(count)) count = 1;
                count = Math.max(1, Math.min(cap, count));

                var poolValue = count * ASSET_VALUE;
                var deferredGain = poolValue * GAIN_FRACTION;

                if (d.identificationRule === 'two_hundred') deferredGain *= 0.95;
                else if (d.identificationRule === 'ninety_five') deferredGain *= 0.85;

                /* v1.0.0 rolled `Math.random() < 0.15` here, so the same decisions
                   scored differently on every run and undo+replay re-rolled the dice.
                   The uninsured QI now carries that tail deterministically as an
                   expected-value haircut; the debrief names the 15% explicitly. */
                if (d.qiSelection === 'cheap') {
                    deferredGain *= QI_UNINSURED_HAIRCUT;
                    trustDelta -= 4;
                    narrativeKey = 'r2_qi_cheap_narr';
                } else if (d.qiSelection === 'premium') {
                    deferredGain *= 1.05;
                    narrativeKey = 'r2_qi_premium_narr';
                } else {
                    narrativeKey = 'r2_qi_mid_narr';
                }

                /* The label promises operational drag on a large pool; v1.0.0 modelled
                   none, so pooling the maximum strictly dominated. 45 days to identify
                   and 180 to close does not scale linearly across assets. */
                var drag = count > 3 ? (count - 3) * (count - 3) * 3.0 : 0;
                if (count > 4) trustDelta -= (count - 4);

                taxDeferredDelta = deferredGain;
                ds.taxDeferred += deferredGain;
                ds.assetsExchanged += count;
                ds.assetsRemaining = Math.max(0, (ds.assetsRemaining === undefined ? ASSETS_TOTAL : ds.assetsRemaining) - count);

                if (count >= 3) { debtAddressed += 20; trustDelta += 4; } else { trustDelta -= 2; }
                roundScore = Math.min(95, 40 + deferredGain * 1.2 - drag);
            } else if (period === 3) {
                var wallTotal = ds.maturityWallTotal || MATURITY_WALL;
                var remainingDebt = Math.max(0, wallTotal - (ds.maturityWallCovered || 0));

                if (d.cmbsStrategy === 'refi') {
                    debtAddressed += remainingDebt; equityDelta -= 8;
                    roundScore = 72; narrativeKey = 'r3_refi_narr';
                } else if (d.cmbsStrategy === 'dpo') {
                    debtAddressed += remainingDebt; equityDelta -= 12; trustDelta += 6;
                    roundScore = 82; narrativeKey = 'r3_dpo_narr';
                } else if (d.cmbsStrategy === 'keys') {
                    debtAddressed += remainingDebt; equityDelta -= 18; trustDelta -= 10;
                    roundScore = 55; narrativeKey = 'r3_keys_narr';
                } else {
                    debtAddressed += remainingDebt * 0.9; equityDelta -= 4;
                    roundScore = 68; narrativeKey = 'r3_modify_narr';
                }

                if (d.bankruptcyThreat === 'yes') {
                    recourseAdded += 12; trustDelta -= 5; roundScore -= 10;
                }
            } else if (period === 4) {
                var want = d.upreitDecision === 'partial' ? UPREIT_PARTIAL
                         : (d.upreitDecision === 'reject' ? 0 : UPREIT_ASSETS);
                var available = (ds.assetsRemaining === undefined ? ASSETS_TOTAL : ds.assetsRemaining);
                var rolled = Math.max(0, Math.min(want, available));
                var scale = want > 0 ? (rolled / want) : 1;

                if (d.upreitDecision === 'accept') {
                    taxDeferredDelta = 55 * scale; equityDelta += 12 * scale; trustDelta -= 3;
                    roundScore = 74; narrativeKey = 'r4_accept_narr';
                } else if (d.upreitDecision === 'reject') {
                    taxDeferredDelta = 0; equityDelta += 8; trustDelta += 2;
                    roundScore = 68; narrativeKey = 'r4_reject_narr';
                    var sold = Math.min(UPREIT_PARTIAL, available);
                    ds.assetsSold += sold;
                    ds.assetsRemaining = Math.max(0, available - sold);
                } else if (d.upreitDecision === 'partial') {
                    taxDeferredDelta = 30 * scale; equityDelta += 10 * scale; trustDelta += 2;
                    roundScore = 76; narrativeKey = 'r4_partial_narr';
                } else {
                    taxDeferredDelta = 48 * scale; equityDelta += 16 * scale; trustDelta += 4;
                    roundScore = 85; narrativeKey = 'r4_counter_narr';
                }

                if (want > 0) {
                    ds.assetsRolledUp += rolled;
                    ds.assetsRemaining = Math.max(0, available - rolled);
                }

                var lockup = parseInt(d.lockupDays, 10);
                if (isFinite(lockup)) {
                    if (lockup > 365) trustDelta -= 3;
                    else if (lockup < 180) trustDelta += 2;
                }
                ds.taxDeferred += taxDeferredDelta;
            } else if (period === 5) {
                var extBonus = d.fundExtension === 'extend1' ? 5
                             : (d.fundExtension === 'extend2' ? 2 : -2);
                var extraYears = d.fundExtension === 'extend1' ? 1
                               : (d.fundExtension === 'extend2' ? 2 : 0);
                ds.fundLifeYears = FUND_LIFE_YEARS + extraYears;

                var waiverBonus = 0;
                if (d.promoteWaiver === 'full') { waiverBonus = 12; trustDelta += 15; }
                else if (d.promoteWaiver === 'partial') { waiverBonus = 8; trustDelta += 8; }
                else { waiverBonus = 0; trustDelta -= 10; }

                roundScore = 60 + extBonus + waiverBonus;
                narrativeKey = 'r5_summary_narr';
            }

            /* ---- apply the deltas once, for every round ---- */
            var wallTot = ds.maturityWallTotal || MATURITY_WALL;
            ds.maturityWallCovered = Math.min(wallTot,
                Math.round(((ds.maturityWallCovered || 0) + debtAddressed) * 10) / 10);
            ds.fundEquity = Math.round(((ds.fundEquity || 0) + equityDelta) * 10) / 10;
            ds.recourseExposure = (ds.recourseExposure || 0) + recourseAdded;
            ds.lpTrust = Math.max(0, Math.min(100, (ds.lpTrust || 0) + trustDelta));
            roundScore = Math.max(0, Math.min(100, roundScore));

            /* ---- headline metrics ------------------------------------------
             * v1.0.0 reported irr = 0.08 * (equity/113) * (1 + deferred/200)
             *                      * (lpTrust/100)
             * which handed a +5.6% "LP Net IRR" to a fund sitting at 0.74x MOIC,
             * and moved that IRR when LP trust moved without any cash flow. IRR
             * is now annualised straight off the equity multiple over the fund
             * life, so the two headline numbers can never contradict each other
             * and the Round 5 extension decision shows up where it belongs.
             * ---------------------------------------------------------------- */
            var years = Math.max(1, parseFloat(ds.fundLifeYears) || FUND_LIFE_YEARS);
            var taxSaved = (ds.taxDeferred || 0) * TAX_RATE;
            var equityMult = ((ds.fundEquity || 0) + taxSaved) / CONTRIBUTED_EQUITY;
            var irr = Math.pow(Math.max(0.0001, equityMult), 1 / years) - 1;
            if (!isFinite(irr)) irr = 0;

            ds.scoreHistory.push(Math.round(roundScore));
            ds.irrHistory.push(Math.round(irr * 1000) / 10);
            ds.equityHistory.push(Math.round(equityMult * 100) / 100);
            ds.taxDeferredHistory.push(Math.round(ds.taxDeferred));
            ds.trustHistory.push(Math.round(ds.lpTrust));

            return {
                period: period,
                roundScore: Math.round(roundScore),
                irr: Math.round(irr * 1000) / 10,
                equityMultiple: Math.round(equityMult * 100) / 100,
                taxDeferredDelta: Math.round(taxDeferredDelta),
                taxDeferredTotal: Math.round(ds.taxDeferred),
                taxSaved: Math.round(taxSaved),
                fundEquity: Math.round(ds.fundEquity),
                lpTrust: Math.round(ds.lpTrust),
                maturityCoverage: Math.max(0, Math.min(100,
                    Math.round((ds.maturityWallCovered / wallTot) * 100))),
                recourseExposure: Math.round(ds.recourseExposure),
                debtAddressed: Math.round(debtAddressed),
                dryPowder: ds.cashReserves,
                assetsRemaining: ds.assetsRemaining,
                fundLifeYears: ds.fundLifeYears,
                narrativeKey: narrativeKey,
                narrative: narrativeKey ? this._t(narrativeKey) : ''
            };
        }

        /* =============================================================== *
         * UI
         * =============================================================== */
        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('fundEquityDisplay', 'domainState.fundEquity', (v) => '$' + Math.round(v || 0) + 'M');
            uiManager.bind('taxDeferredDisplay', 'domainState.taxDeferred', (v) => '$' + Math.round(v || 0) + 'M');
            uiManager.bind('maturityCoverDisplay', 'domainState.maturityWallCovered', (v) => '$' + Math.round(v || 0) + 'M');
            uiManager.bind('lpTrustDisplay', 'domainState.lpTrust', (v) => Math.round(v || 0) + '/100');
            uiManager.bind('recourseDisplay', 'domainState.recourseExposure', (v) => '$' + Math.round(v || 0) + 'M');
            uiManager.bind('cashDisplay', 'domainState.cashReserves', (v) => '$' + (Math.round((v || 0) * 10) / 10) + 'M');
            this._wire();
        }

        _paint(state) {
            var st = state || (window.mySimulation && window.mySimulation.state) || {};
            var max = parseInt(st.maxPeriods, 10) || 5;
            var period = parseInt(st.currentPeriod, 10) || 1;
            if (period > max) period = max;
            if (period < 1) period = 1;

            var titleEl = document.getElementById('briefingTitle');
            if (titleEl) {
                titleEl.setAttribute('data-i18n', 'round' + period + '_title');
                titleEl.textContent = this._t('round' + period + '_title');
            }
            /* Briefing bodies carry <br> markup and are authored content from this
               adapter's own translation table — never learner input. vcI18n writes
               data-i18n via textContent, which would show the tags literally, so the
               element is driven through data-i18n-html instead. */
            var descEl = document.getElementById('briefingText');
            if (descEl) {
                descEl.setAttribute('data-i18n-html', 'round' + period + '_briefing');
                descEl.innerHTML = this._t('round' + period + '_briefing');
            }
            for (var i = 1; i <= max; i++) {
                var panel = document.getElementById('round' + i + 'Controls');
                if (panel) panel.style.display = (i === period) ? 'block' : 'none';
            }
            var pill = document.getElementById('roundStatus');
            if (pill) {
                pill.textContent = this._isComplete(st)
                    ? this._t('status_complete')
                    : this._t('status_round_of', { n: period, total: max });
            }
            var bar = document.getElementById('periodProgress');
            if (bar) bar.setAttribute('aria-label', this._t('progress_label'));
            var irrCanvas = document.getElementById('irrChart');
            if (irrCanvas) irrCanvas.setAttribute('aria-label', this._t('chart_irr_alt'));
            var scoreCanvas = document.getElementById('scoreChart');
            if (scoreCanvas) scoreCanvas.setAttribute('aria-label', this._t('chart_score_alt'));

            this._syncInventory(st);
        }

        /* Round 2 cannot pool assets the fund no longer owns, and has to leave
           enough standing for the Round 4 §721 roll-up. */
        _syncInventory(state) {
            var ds = (state && state.domainState) || {};
            var remaining = (typeof ds.assetsRemaining === 'number' && isFinite(ds.assetsRemaining))
                ? ds.assetsRemaining : ASSETS_TOTAL;
            var total = ds.assetsTotal || ASSETS_TOTAL;
            var cap = this._maxRelinquish(ds);

            var inp = document.getElementById('relinquishedCountInput');
            if (inp) {
                inp.setAttribute('max', String(cap));
                var cur = parseInt(inp.value, 10);
                if (isFinite(cur) && cur > cap) inp.value = String(cap);
            }
            var lab = document.getElementById('relinquishedLabel');
            if (lab) lab.textContent = this._t('relinquished_label', { max: cap });
            var note = document.getElementById('inventoryNote');
            if (note) {
                note.textContent = this._t('inventory_note', {
                    remaining: remaining, total: total, needed: UPREIT_ASSETS, max: cap
                });
            }
        }

        _showNarrative(state) {
            var box = document.getElementById('roundNarrativeBox');
            var el = document.getElementById('roundNarrative');
            if (!el) return;
            var st = state || {};
            var hist = Array.isArray(st.history) ? st.history : [];
            var res = hist.length ? (hist[hist.length - 1].results || {}) : null;
            if (!res || !(res.narrativeKey || res.narrative)) {
                el.textContent = '';
                if (box) box.style.display = 'none';
                return;
            }
            if (box) box.style.display = 'block';
            /* re-resolve through i18n so the outcome follows a language change */
            el.textContent = res.narrativeKey ? this._t(res.narrativeKey) : String(res.narrative);
            var lbl = document.getElementById('roundNarrativeLabel');
            if (lbl) lbl.textContent = this._t('outcome_heading', { n: res.period || hist.length });
        }

