        /* getChartConfig() only runs once, so the titles are re-stamped here on a
           language change. updateChart() Object.assigns the dataset, so the dataset
           labels come back through getChartData(). */
        _localiseCharts() {
            try {
                var sim = window.mySimulation;
                var charts = sim && sim.uiManager && sim.uiManager.charts;
                if (!charts) return;
                var map = { irrChart: 'chart_irr_title', scoreChart: 'chart_score_title' };
                var self = this;
                Object.keys(map).forEach(function(id) {
                    var c = charts[id];
                    if (!c || !c.options || !c.options.plugins || !c.options.plugins.title) return;
                    c.options.plugins.title.text = self._t(map[id]);
                    if (typeof c.update === 'function') c.update();
                });
                if (typeof sim.updateCharts === 'function') sim.updateCharts();
            } catch (e) { /* charts are optional */ }
        }

        /* Guarded: updateCharts() swallows throws, so an unguarded deref here would
           show up as "the charts silently stopped updating". */
        getChartData(state) {
            var ds = (state && state.domainState) || {};
            var irr = Array.isArray(ds.irrHistory) ? ds.irrHistory : [];
            var score = Array.isArray(ds.scoreHistory) ? ds.scoreHistory : [];
            var n = Math.max(irr.length, score.length);
            var labels = [];
            for (var i = 0; i < n; i++) labels.push(this._t('chart_round_short', { n: i + 1 }));
            return {
                irrChart:   { labels: labels, datasets: [{ label: this._t('chart_irr_dataset'), data: irr }] },
                scoreChart: { labels: labels, datasets: [{ label: this._t('chart_score_dataset'), data: score }] }
            };
        }

        /* =============================================================== *
         * Debrief
         * =============================================================== */
        getPerformanceSummary(history) {
            var h = Array.isArray(history) ? history : [];
            if (!h.length) {
                return {
                    totalPeriods: 0, totalScore: 0, finalIRR: 0, equityMultiple: 0,
                    taxDeferred: 0, taxSaved: 0, performance: this._t('rating_emerging'),
                    performanceKey: 'rating_emerging', insights: [], message: this._t('summary_empty')
                };
            }
            var final = h[h.length - 1].results || {};
            var sum = 0, n = 0;
            h.forEach(function(rec) {
                var s = rec.results && rec.results.roundScore;
                if (typeof s === 'number' && isFinite(s)) { sum += s; n++; }
            });
            var avg = n ? sum / n : 0;
            var perfKey = avg > 80 ? 'rating_top' : (avg > 70 ? 'rating_solid' : 'rating_emerging');

            var lastDomain = h[h.length - 1].domainState || {};
            var decisions = {};
            h.forEach(function(rec) { Object.assign(decisions, rec.decisions || {}); });

            var deferred = final.taxDeferredTotal || 0;
            var taxSaved = Math.round(deferred * TAX_RATE);
            var insights = [];

            insights.push(deferred > 80
                ? this._t('insight_tax_strong', { gain: Math.round(deferred), saved: taxSaved })
                : this._t('insight_tax_weak', { gain: Math.round(deferred), saved: taxSaved }));

            insights.push((final.maturityCoverage || 0) >= 95
                ? this._t('insight_wall_ok', { pct: final.maturityCoverage || 0 })
                : this._t('insight_wall_short', { pct: final.maturityCoverage || 0 }));

            insights.push((final.lpTrust || 0) > 75
                ? this._t('insight_trust_ok', { trust: final.lpTrust || 0 })
                : this._t('insight_trust_weak', { trust: final.lpTrust || 0 }));

            if ((final.recourseExposure || 0) > 10) {
                insights.push(this._t('insight_recourse', { amt: final.recourseExposure }));
            }
            if (decisions.qiSelection === 'cheap') {
                insights.push(this._t('insight_qi_tail', { odds: QI_FAILURE_ODDS }));
            }
            if (decisions.promoteWaiver === 'none') {
                insights.push(this._t('insight_promote_none'));
            }
            var held = (lastDomain.assetsRemaining === undefined) ? null : lastDomain.assetsRemaining;
            if (held !== null) {
                insights.push(this._t('insight_disposition', {
                    keys: lastDomain.assetsHandledKeys || 0,
                    exchanged: lastDomain.assetsExchanged || 0,
                    rolled: lastDomain.assetsRolledUp || 0,
                    sold: lastDomain.assetsSold || 0,
                    held: held,
                    total: lastDomain.assetsTotal || ASSETS_TOTAL
                }));
            }

            return {
                totalPeriods: h.length,
                totalScore: Math.round(avg),
                finalIRR: final.irr,
                equityMultiple: final.equityMultiple,
                taxDeferred: deferred,
                taxSaved: taxSaved,
                lpTrust: final.lpTrust,
                maturityCoverage: final.maturityCoverage,
                recourseExposure: final.recourseExposure,
                fundEquity: final.fundEquity,
                dryPowder: lastDomain.cashReserves,
                fundLifeYears: final.fundLifeYears || lastDomain.fundLifeYears || FUND_LIFE_YEARS,
                performance: this._t(perfKey),
                performanceKey: perfKey,
                insights: insights,
                message: this._t('summary_message', { rating: this._t(perfKey), score: Math.round(avg) })
            };
        }

        /* v1.0.0 never implemented this, so usf-adapter.js:600 rendered
           "You completed N periods … Thank you for participating!" and discarded
           every number getPerformanceSummary() had just computed. */
        formatCompletionMessage(summary) {
            var s = summary || {};
            var self = this;
            var entryMult = Math.round((OPENING_EQUITY / CONTRIBUTED_EQUITY) * 100) / 100;
            var entryIrr = Math.round((Math.pow(OPENING_EQUITY / CONTRIBUTED_EQUITY, 1 / FUND_LIFE_YEARS) - 1) * 1000) / 10;

            var irr = (typeof s.finalIRR === 'number' && isFinite(s.finalIRR)) ? s.finalIRR : 0;
            var moic = (typeof s.equityMultiple === 'number' && isFinite(s.equityMultiple)) ? s.equityMultiple : 0;

            function metric(labelKey, value, cls) {
                return '<div class="reit-sim-complete-metric">'
                     + '<div class="m-label">' + self._t(labelKey) + '</div>'
                     + '<div class="m-value' + (cls ? ' ' + cls : '') + '">' + value + '</div></div>';
            }

            var html = '<div class="reit-sim-complete">'
                + '<h3>' + this._t('complete_heading') + '</h3>'
                + '<div class="reit-sim-complete-sub">' + this._t('complete_sub', {
                        rounds: s.totalPeriods || 0, years: s.fundLifeYears || FUND_LIFE_YEARS }) + '</div>'
                + '<div class="reit-sim-rating">' + (s.performance || '') + '</div>'
                + '<div class="reit-sim-complete-grid">'
                + metric('complete_score', (s.totalScore || 0) + '/100')
                + metric('complete_irr', irr.toFixed(1) + '%', irr < 0 ? 'neg' : 'pos')
                + metric('complete_moic', moic.toFixed(2) + 'x', moic < 1 ? 'neg' : 'pos')
                + metric('complete_gain', '$' + Math.round(s.taxDeferred || 0) + 'M')
                + metric('complete_taxsaved', '$' + Math.round(s.taxSaved || 0) + 'M')
                + metric('complete_equity', '$' + Math.round(s.fundEquity || 0) + 'M')
                + metric('complete_trust', Math.round(s.lpTrust || 0) + '/100')
                + metric('complete_coverage', Math.round(s.maturityCoverage || 0) + '%')
                + metric('complete_recourse', '$' + Math.round(s.recourseExposure || 0) + 'M',
                         (s.recourseExposure || 0) > 10 ? 'neg' : '')
                + '</div>'
                + '<div class="reit-sim-complete-context">' + this._t('complete_context', {
                        entryMoic: entryMult.toFixed(2), entryIrr: entryIrr.toFixed(1),
                        moic: moic.toFixed(2), irr: irr.toFixed(1) }) + '</div>'
                + '<h4>' + this._t('complete_insights') + '</h4><ul>';
            (s.insights || []).forEach(function(line) { html += '<li>' + line + '</li>'; });
            html += '</ul></div>';
            return html;
        }

        getHint(state, results) {
            if (!results) return null;
            /* getHint() runs AFTER PeriodManager incremented currentPeriod, so gate on
               results.period — the round that was actually just played. */
            var played = parseInt(results.period, 10);
            if (!isFinite(played)) played = parseInt(state && state.currentPeriod, 10) || 1;
            if (results.lpTrust < 50) return this._t('hint_lp_trust');
            if (played >= 3 && results.maturityCoverage < 60) return this._t('hint_maturity');
            if (results.recourseExposure > 10) return this._t('hint_recourse');
            if (played >= 2 && results.taxDeferredTotal < 30) return this._t('hint_tax');
            return null;
        }

