    document.addEventListener('DOMContentLoaded', () => {
        window.mySimulation = new USF.SimulationFramework();
        /* score mirror 2026-11-11: copies the score this adapter already computes into domainState.performance.overallScore */
        (function (P) {
          var orig = P.calculateResults;
          var ok = function (v) { v = parseFloat(v); return isFinite(v) && v >= 0 && v <= 100; };
          P.calculateResults = function (s) {
            var r = orig.apply(this, arguments);
            try {
              var ds = s && s.domainState;
              if (ds && !(ds.performance && ok(ds.performance.overallScore) && !ds.performance.mirrored)) {
                var v = null, c = [ds.overallScore, ds.score, ds.totalScore, ds.composite, ds.compositeScore], i;
                for (i = 0; i < c.length && v === null; i++) { if (ok(c[i])) { v = parseFloat(c[i]); } }
                if (v === null && typeof this.getPerformanceSummary === 'function') {
                  var h = (s.history || []).concat([{ period: s.currentPeriod, decisions: JSON.parse(JSON.stringify(s.decisions || {})), results: r, domainState: ds }]);
                  var m = this.getPerformanceSummary(h) || {};
                  var k = ['overallScore', 'score', 'totalScore', 'composite', 'finalScore', 'compositeScore', 'performanceScore'];
                  for (i = 0; i < k.length && v === null; i++) { if (ok(m[k[i]])) { v = parseFloat(m[k[i]]); } }
                }
                if (v !== null) {
                  v = Math.round(v * 10) / 10;
                  if (!ds.performance || typeof ds.performance !== 'object') { ds.performance = {}; }
                  ds.performance.overallScore = v;
                  ds.performance.mirrored = true;
                }
              }
            } catch (e) { }
            return r;
          };
        })(REITPlayAdapter.prototype);
        window.mySimulation.initialize(new REITPlayAdapter(), {
            simulationType: 'reit_play_workout',
            maxPeriods: 5,
            autoSaveInterval: 30000
        });
    });
})();
